-- ============================================================
-- RedNorte - Seed DEMO realista (sistema en uso)
-- 32 consultas, agenda con horas tomadas, auditoria activa
-- ============================================================
USE db_consultas;
DELETE FROM consultas;
SELECT CONCAT('Consultas demo cargadas: ', COUNT(*)) AS estado FROM consultas;

USE db_agenda;
DELETE FROM bloques_agenda;
SELECT CONCAT('Agenda demo cargada: ', COUNT(*), ' bloques') AS estado FROM bloques_agenda;

USE db_auditoria;
DELETE FROM registros_auditoria;
SELECT CONCAT('Auditoria demo cargada: ', COUNT(*), ' registros') AS estado FROM registros_auditoria;
